// Itqān · Lage der Ziffern in der Versmarke jeder Āya, aus den Schriftzeichen der jeweiligen Seite gemessen (entwuerfe/stoppzeichen/messen_vers.html).
// Je Āya 8 Zeichen: links, oben, rechts, unten als je zwei Ziffern im 36er System, in Tausendstel der Schriftgröße von der linken oberen Ecke des Zeichens.
// Damit wird nur die Zahl schwarz, die Versmarke selbst bleibt golden. Jede Seitenschrift zeichnet sie etwas anders, deshalb gilt der Wert je Āya.
const TAB = "";
export function zifferClip(vi) {
  const s = TAB.substr(vi * 8, 8); if (s.length < 8 || s === '00000000') return '';
  const [l, o, r, u] = [0, 2, 4, 6].map(k => parseInt(s.substr(k, 2), 36) / 1000);
  return `inset(${o}em calc(100% - ${r}em) calc(100% - ${u}em) ${l}em round .03em)`;
}
